int n;
vi a(20);
vvi op;

void moveall(int k, int s, int t)
{
    if(k <= 0) return;
    int u = 6 - s - t;

    if(a[k - 1] == 0)
    {
        moveall(k - 1, s, u);
        op.pb({k, s, t});
        moveall(k - 1, u, t);
    }
    else
    {
        moveall(k - 1 - a[k - 1], s, u);
        op.pb({k, s, t});
        moveall(k - 1 - a[k - 1], u, s);
        moveall(k - 1, s, t);
    }
}

int main()
{
    ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);

	int t;
	cin >> t;

	while(t-->0)
    {
        cin >> n;

        for(int i=0; i<n; i++) cin >> a[i];

        bool ok = true;
        for(int i=0; i<n; i++) if(a[i] > i) ok = false;

        if(!ok)
        {
            cout << "NO\n";
            continue;
        }

        cout << "YES\n";

        moveall(n, 1, 3);

        cout << op.size() << "\n";
        for(vi p: op) cout << p[0] << " " << p[1] << " " << p[2] << "\n";
        op.clear();
    }
}

#include <bits/stdc++.h>
#define pb push_back

using namespace std;

typedef long long ll;
typedef vector<int> vi;
typedef vector<vi> vvi;
typedef vector<ll> vll;
typedef vector<vll> vvll;
typedef pair<int, int> pii;
typedef pair<ll, ll> pll;

const ll N = 1000000007;
#define MAX_N 200005

vll fac(MAX_N, 1);

int main()
{
    ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);

	for(int i=2; i<MAX_N; i++) fac[i] = (i * fac[i - 1]) % N;

	int t = 1;
	cin >> t;
    while(t-->0)
    {
        ll n, k;
        cin >> n >> k;

        vvi D; vi d;
        bool ok = true;

        for(int i=0; i<k; i++)
        {
            ll s, r, c;
            cin >> s >> r >> c;

            //Starting Point Check
            if(s / 2 + r + c != n + 1) ok = false;

            vector<pii> V;
            V.pb({r, c});

            if(s != 1)
            {
                string S;
                cin >> S;

                for(char C: S)
                {
                    if(C == 'R')
                    {
                        c++;
                        V.pb({r, c});
                    }
                    else
                    {
                        r++;
                        V.pb({r, c});
                    }
                }

                //Symmetry Check
                for(int i=0; i<s/2; i++) if(V[i].second - V[i].first != V[s - i - 1].second - V[s - i - 1].first) ok = false;
            }

            //Info Handling
            if(!ok) continue;

            if(D.size() < s / 2 + 1)
            {
                D.resize(s / 2 + 1);
                d.resize(s / 2 + 1);
            }

            for(int i=0; i<s/2+1; i++) D[i].pb(V[s/2-i].second);
            d[s / 2] = V[0].second;
        }

        if(!ok)
        {
            cout << "0\n";
            continue;
        }

        int x = D.size();
        for(int i=0; i<x; i++) sort(D[i].begin(), D[i].end());

        D.pb({});

        ll ans = 1;
        for(int i=0; i<x; i++)
        {
            if(!ok)
            {
                ans = 0;
                continue;
            }

            bool dec = false;

            int l = 0, k = 0;

            while(l + k < D[i].size())
            {
                if(D[i][l + k] == d[i])
                {
                    k++;
                    continue;
                }

                if(D[i][l + k] == D[i + 1][l])
                {
                    if(dec)
                    {
                        ok = false;
                        break;
                    }
                }
                else if(D[i][l + k] - 1 == D[i + 1][l])
                {
                    if(!dec)
                    {
                        if(l + k == 0 && d[i] == 0) ans *= D[i][l + k] - 1;
                        else if(l + k != 0 && d[i] == 0) ans *= D[i][l + k] - D[i][l + k - 1] - 1;
                        ans %= N;
                    }

                    dec = true;
                }
                else
                {
                    ok = false;
                    break;
                }

                l++;
            }

            if(!dec)
            {
                if(d[i] == 0) ans *= n - i - D[i][l + k - 1];
                ans %= N;
            }
        }

        ans *= fac[n - x];
        ans %= N;

        cout << ans << "\n";
    }
}

#include <bits/stdc++.h>
#define pb push_back

using namespace std;

typedef long long ll;
typedef vector<int> vi;
typedef vector<vi> vvi;
typedef vector<ll> vll;
typedef vector<vll> vvll;
typedef pair<int, int> pii;
typedef pair<ll, ll> pll;

// function to find the solution
ll gcd(ll a, ll b, ll &x, ll &y){
    if(b == 0){
        x= 1; y = 0;
        return a;
    }
    ll x1, y1;
    ll d = gcd(b, a%b, x1, y1);
    x = y1;
    y = x1 - y1*(a/b);
    return d;
}

int main()
{
    ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);

	int t = 1;
	cin >> t;
    while(t-->0)
    {
        ll n, a, b, k;
        cin >> n >> a >> b >> k;

        ll g = __gcd(a, b);

        if(k % g != 0)
        {
            cout << "0\n";
            continue;
        }

        a /= g; b /= g; k /= g;

        if(a == 1 && b == 1)
        {
            cout << n << "\n";
            continue;
        }

        /// STEP 1
        ll ans = 0;
        if(k % a == 0)
        {
            ans++; n--;
            ll x = k / a;
            while(n > 0)
            {
                if(k - (x * b) < 0 || (k - x * b) % a != 0) break;

                x = (k - x * b) / a;
                ans++;
                n--;
            }
        }

        /// STEP 2
        ll v = 0;
        if(k % (a + b) == 0) v = 1e9;
        else
        {
            if(a < b) swap(a, b);
            /// SOLVE (a + b) x + b * a^v y = k
            ll m = b;
            while(true)
            {
                ll x, y;
                gcd(a + b, m, x, y);

                if(x < 0) {x += m; y -= a + b;}
                x *= k; y *= k;
                ll d = x / m;
                x -= d * m; y += d * (a + b);
                //cout << x << " " << y << "\n";
                //getchar();

                if(m / b * y + x < 0) break;

                /// Secondary Check
                bool ok = true;
                ll x1 = x, x2 = m / b * y + x;
                for(int _=0; _<v; _++)
                {
                    if(a * x1 + b * x2 != k) ok = false;

                    if((k - b * x1) % a)
                    {
                        ok = false;
                        break;
                    }

                    x2 = x1;
                    x1 = (k - b * x1) / a;
                }

                if(!ok) break;

                v++;

                if(a > k / m) break;
                m *= a;
            }
        }

        //cout << "! " << v << "\n";

        cout << ans + (n - (n + v) / (v + 1)) << "\n";
    }
}
